INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 9, 3, 'When many companies moved to remote work, managers feared that productivity would drop. Early surveys, however, told a more complicated story. Employees reported getting more focused work done at home, free from the interruptions of an open-plan office. Yet the same workers also said they found it harder to learn from colleagues and to feel part of a team. Several firms have therefore adopted a hybrid model, in which staff spend part of the week at the office. Critics argue that this merely shifts the problem, since the days people choose to attend are rarely the same, leaving the office half-empty and collaboration no easier.', 'What does the passage say about early surveys?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 9 FROM tests t WHERE t.code = 'FEA_BANK_B2_S1' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 9);
