INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 9, 3, 'Several companies that tested a four-day working week reported surprising results. Employees worked fewer hours but, according to managers, the quality of their output did not fall. Many staff said they felt less stressed and took fewer sick days. Employers also noticed that workers wasted less time in meetings, because they knew that time was limited. Nevertheless, the idea is not suitable for every sector. Hospitals, for instance, cannot simply close for a day, and employees in customer-facing roles may need to cover longer shifts to keep services running. Supporters therefore suggest that each organisation should adapt the model to its own circumstances rather than copy a standard timetable.', 'What did managers say about the quality of work during the trial?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 9 FROM tests t WHERE t.code = 'FEA_BANK_B2_S3' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 9);
