INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 9, 3, 'Public debate about artificial intelligence often assumes that technological change arrives suddenly and from outside, like weather. Historians of technology find this picture misleading. New tools are shaped by the people who fund, design and regulate them, and their effects depend as much on social choices as on engineering. The introduction of electricity, for instance, did not raise factory output until owners redesigned their workplaces around electric motors, a process that took decades. If the pattern holds, the most important question about any new technology is not what it can do, but who decides how it is used, and for whose benefit.', 'What is the author’s main point?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 9 FROM tests t WHERE t.code = 'FEA_BANK_C1_S1' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 9);
