INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 9, 3, 'It is commonly assumed that more choice makes people happier, yet research suggests otherwise. In one well-known study, shoppers offered a large range of jams were far less likely to buy any than those offered a small selection. Psychologists explain this by noting that abundant options raise expectations and make it easier to regret the option not taken. The effect is not universal: people who know exactly what they want, or who delegate decisions to trusted advisers, seem largely immune. Critics also point out that the original findings have been hard to replicate consistently. The most defensible conclusion, then, is not that choice is harmful, but that its value depends on how much guidance people have in navigating it.', 'What does the jam study suggest?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 9 FROM tests t WHERE t.code = 'FEA_BANK_C1_S2' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 9);
