INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 9, 3, 'Boredom is usually treated as a problem to be solved, preferably with a smartphone. Yet some researchers argue that moments of boredom serve a purpose. When the mind is not occupied by a task, it tends to wander, and this wandering has been linked to creative thinking and long-term planning. In one experiment, participants who first completed a deliberately dull task later produced more imaginative uses for everyday objects than those who had not. The researchers are careful to add that boredom is not enjoyable and that persistent boredom is associated with poorer well-being. Their claim is a modest one: occasional, unstructured downtime may help thinking, so filling every spare minute with stimulation may carry a hidden cost.', 'What do the researchers suggest about mind-wandering?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 9 FROM tests t WHERE t.code = 'FEA_BANK_C1_S3' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 9);
