INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 5, 3, 'Anyone who has tried to translate a poem knows that fidelity and fluency pull in opposite directions. A translator who clings to the literal sense risks producing awkward, lifeless prose; one who prizes elegance may quietly replace the author’s meaning with her own. Some theorists therefore reject the notion of a “faithful” translation altogether, arguing that every rendering is an interpretation and that the translator’s visibility should be acknowledged rather than concealed. Others counter that this view, taken to its conclusion, licenses carelessness: if no translation can be faithful, why labour to be accurate? The more persuasive position may be that perfect equivalence is unattainable, while relative fidelity remains a meaningful standard against which individual choices can be judged.', 'What dilemma does the author describe?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 5 FROM tests t WHERE t.code = 'FEA_BANK_C2_S2' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 5);
