INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'A', 'fidelity should be abandoned as a goal', 0, 1 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_BANK_C2_S2' AND x.question_number = 7;
INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'B', 'literal translation is always best', 0, 2 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_BANK_C2_S2' AND x.question_number = 7;
