INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, NULL, 5, 3, 'Nostalgia was once classified as a medical disorder, a malady of soldiers and exiles whose longing for home was thought to produce fever and despair. Today, researchers are more likely to describe it as a psychological resource. Reflecting on cherished memories seems to bolster self-esteem and strengthen a sense of belonging, particularly in periods of upheaval. Yet nostalgia is not invariably benign. Critics observe that it tends to flatten the past into a sequence of golden moments, editing out hardship and injustice, and that political movements have exploited this selective memory to promise a return to a time that never quite existed. The healthiest form, some suggest, is one that remains aware of what has been omitted.', 'How has the scientific view of nostalgia changed?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 5 FROM tests t WHERE t.code = 'FEA_BANK_C2_S3' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 5);
