INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'A', 'solves the problem completely', 0, 1 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_FORM_A' AND x.question_number = 27;
INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'B', 'is worse than remote work', 0, 2 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_FORM_A' AND x.question_number = 27;
INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'C', 'is popular with managers', 0, 3 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_FORM_A' AND x.question_number = 27;
INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'D', 'moves the problem without solving it', 1, 4 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_FORM_A' AND x.question_number = 27;
INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, (SELECT s.id FROM sections s WHERE s.test_id = t.id AND s.name = 'C1' LIMIT 1), 28, 3, 'Public debate about artificial intelligence often assumes that technological change arrives suddenly and from outside, like weather. Historians of technology find this picture misleading. New tools are shaped by the people who fund, design and regulate them, and their effects depend as much on social choices as on engineering. The introduction of electricity, for instance, did not raise factory output until owners redesigned their workplaces around electric motors, a process that took decades. If the pattern holds, the most important question about any new technology is not what it can do, but who decides how it is used, and for whose benefit.', 'What is the author’s main point?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 28 FROM tests t WHERE t.code = 'FEA_FORM_A' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 28);
INSERT IGNORE INTO question_options (question_id, option_label, option_text, is_correct, display_order) SELECT x.id, 'A', 'Technology develops too fast for regulation.', 0, 1 FROM questions x JOIN tests t ON t.id = x.test_id WHERE t.code = 'FEA_FORM_A' AND x.question_number = 28;
