INSERT INTO questions (test_id, section_id, question_number, part_number, stimulus_text, question_text, question_type, instructions, points, display_order) SELECT t.id, (SELECT s.id FROM sections s WHERE s.test_id = t.id AND s.name = 'B2' LIMIT 1), 26, 3, 'In recent years, beehives have appeared on the roofs of offices, hotels and even museums in many large cities. Supporters claim that urban bees often do better than their rural cousins, since cities offer a wide variety of flowers in parks and gardens through most of the year, while farmland may provide only one crop at a time. Some conservationists, however, warn that the trend can backfire. Honeybees are not endangered, and when too many hives are placed in one area, they compete with wild bees for the same food. The best help for pollinators, these experts say, is to plant more flowers rather than to add more hives.', 'What is the conservationists’ main concern?', 'multiple_choice_single', 'Read the passage, then choose the best answer.', 1.0, 26 FROM tests t WHERE t.code = 'FEA_FORM_B' AND NOT EXISTS (SELECT 1 FROM questions x WHERE x.test_id = t.id AND x.question_number = 26);
